script:
getgenv().AutoFarm = true;

game:GetService("RunService").Heartbeat:Connect(function()
   if getgenv().AutoFarm then
       game:GetService("ReplicatedStorage").Remotes.addGems:FireServer("gem18");
       game:GetService("ReplicatedStorage").Remotes.addCash:FireServer();
       game:GetService("ReplicatedStorage").Remotes.pickUpCash:FireServer("cash18");
   end
end)
